INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24901, 'Luke 24:37', 'Luke', 24, 37, '&nbsp;هغوئ يرې او هيبت واخستل او په دې سوچ کښې شُو چې ګنې پيرے يې وليدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24902, 'Luke 24:38', 'Luke', 24, 38, '&nbsp;خو هغۀ ورته وفرمائيل چې، ”تاسو داسې وار خطا ولې يئ او ځان سره ولې وايئ چې دا څوک دے؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24903, 'Luke 24:39', 'Luke', 24, 39, '&nbsp;زما لاسونو او پښو ته خيال وکړئ چې دا زۀ په خپله يم. ما له لاس راوړئ او وګورئ، د پيرى بدن نۀ وى لکه څنګه چې زما دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24904, 'Luke 24:40', 'Luke', 24, 40, '&nbsp;کله چې هغۀ دا خبرې وکړې نو خپل لاسونه او پښې يې هغوئ ته وښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24905, 'Luke 24:41', 'Luke', 24, 41, '&nbsp;د هغوئ د خوشحالۍ په وجه اوس لا هم په هغۀ باور نۀ راتلو او حېران وُو، نو هغۀ هغوئ ته وفرمائيل چې، ”تاسو سره د خوراک څۀ بندوبست شته؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24906, 'Luke 24:42', 'Luke', 24, 42, '&nbsp;نو هغوئ ورله د ماهى يوه وريته شوې ډکره ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24907, 'Luke 24:43', 'Luke', 24, 43, '&nbsp;او هغۀ واخستله او د هغوئ په وړاندې يې وخوړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24908, 'Luke 24:44', 'Luke', 24, 44, '&nbsp;عيسىٰ هغوئ ته وفرمائيل چې، ”دا زما هغه کلام دے چې کله زۀ تاسو سره وم نو درته به مې وئيل چې د موسىٰ په شريعت کښې د نبيانو په صحيفو کښې او په زبور کښې چې څۀ زما په حقله ليکلے شوى دى، هغه به ضرور پوره شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24909, 'Luke 24:45', 'Luke', 24, 45, '&nbsp;بيا هغۀ د هغوئ ذهنونه کولاو کړل چې په صحيفو پوهه شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24910, 'Luke 24:46', 'Luke', 24, 46, '&nbsp;هغۀ هغوئ ته وفرمائيل چې، ”د پخوا نه دا ليکلے شوى دى چې مسيح به زحمت وزغمى او په درېمه ورځ به د مړو نه بيا ژوندے پاڅى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24911, 'Luke 24:47', 'Luke', 24, 47, '&nbsp;او د هغۀ په نامه به ټولو قومونو ته د ګناهونو نه د توبې او د معافۍ وعظ کولے شى. چې د يروشلم نه به شروع شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24912, 'Luke 24:48', 'Luke', 24, 48, '&nbsp;هم تاسو د دې هر څۀ ګواهان يئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24913, 'Luke 24:49', 'Luke', 24, 49, '&nbsp;ګورئ، زۀ تاسو ته هغه څوک درلېږم د چا چې زما پلار تاسو سره وعده کړې وه، خو په دې ښار کښې تر هغې پاتې شئ ترڅو چې په تاسو آسمانى قوت نازل شوے نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24914, 'Luke 24:50', 'Luke', 24, 50, '&nbsp;بيا عيسىٰ هغوئ بهر د بيتِ‌عنياه پورې بوتلل او خپل لاسونه يې اوچت کړل او هغوئ له يې برکت ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24915, 'Luke 24:51', 'Luke', 24, 51, '&nbsp;کله چې هغۀ هغوئ له برکت ورکولو نو هغه د هغوئ نه جدا شو او آسمان ته پورته کړے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24916, 'Luke 24:52', 'Luke', 24, 52, '&nbsp;نو هغوئ د هغۀ عبادت وکړو او ډېر په خوشحالۍ يروشلم ته واپس راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24917, 'Luke 24:53', 'Luke', 24, 53, '&nbsp;او هغوئ خپل ټول وخت د خُدائ پاک په کور کښې د خُدائ په ثنا وئيلو کښې تېرولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24918, 'John 1:1', 'John', 1, 1, '&nbsp;کلام د ازل نه موجود وو او کلام د خُدائ پاک سره وو او هغه کلام خُدائ پاک وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24919, 'John 1:2', 'John', 1, 2, '&nbsp;هغه د ازل نه خُدائ پاک سره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24920, 'John 1:3', 'John', 1, 3, '&nbsp;خُدائ پاک هر څيز د هغۀ په وسيله پېدا کړل، يو پېدا شوے څيز هم بغېر د هغۀ نه پېدا نۀ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24921, 'John 1:4', 'John', 1, 4, '&nbsp;او دغه کلام د ژوند سرچينه وه او هم دا د ټولو انسانانو دپاره نُور وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24922, 'John 1:5', 'John', 1, 5, '&nbsp;او نُور په تيارۀ کښې ځليږى او تيارۀ پرې کله هم غالبه نۀ شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24923, 'John 1:6', 'John', 1, 6, '&nbsp;خُدائ پاک يو سړے راولېږلو چې نوم يې يحيىٰ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24924, 'John 1:7', 'John', 1, 7, '&nbsp;هغه د نُور د ګواهۍ دپاره راغلو چې ټول خلق د هغۀ د پېغام په وسيله ايمان راوړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24925, 'John 1:8', 'John', 1, 8, '&nbsp;هغه په خپله خو نُور نۀ وو خو هغه د نُور د ګواهۍ دپاره راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24926, 'John 1:9', 'John', 1, 9, '&nbsp;هغه حقيقى نُور دُنيا ته راتلونکے وو کوم چې به په هر يو بنى آدم ځليږى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24927, 'John 1:10', 'John', 1, 10, '&nbsp;هغه په خپله هغه دُنيا ته راغلو کومه چې هغۀ پېدا کړې وه خو دُنيا هغه ونۀ پېژندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24928, 'John 1:11', 'John', 1, 11, '&nbsp;هغه خپل قوم ته راغلو خو د هغۀ خپلو خلقو هغه قبول نۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24929, 'John 1:12', 'John', 1, 12, '&nbsp;خو کومو خلقو چې هغه قبول کړو او په هغۀ يې ايمان راوړو نو هغۀ هغوئ ته دا حق ورکړو چې د خُدائ پاک اولاد شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24930, 'John 1:13', 'John', 1, 13, '&nbsp;داسې اولاد چې نۀ په فطرى طور يا په انسانى خواهشاتو بلکې د خُدائ پاک نه پېدا شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24931, 'John 1:14', 'John', 1, 14, '&nbsp;نو کلام انسان شو او هغه زمونږ په مينځ کښې اوسېدو او مونږ د هغۀ لوئى وليدله، د واحد او د اېک يو زوئ لوئى، چې د حقيقت او وفادارۍ نه معمور وى څوک چې د پلار د خوا نه راغلے وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24932, 'John 1:15', 'John', 1, 15, '&nbsp;يحيىٰ د هغۀ په حقله ګواهى وکړه. هغۀ په چغو ووئيل چې، ”دا هغه سړے دے چې ما يې ذکر کړے وو چې هغه هغه څوک دے چې زما نه وروستو به راشى خو زما نه به لوئ وى ځکه چې هغه زما نه وړاندې موجود وو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24933, 'John 1:16', 'John', 1, 16, '&nbsp;ځکه چې مونږ ټولو د هغۀ د ټولې معمورتيا نه په فضل دپاسه فضل وموندلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24934, 'John 1:17', 'John', 1, 17, '&nbsp;ځکه چې شريعت د موسىٰ په وسيله ورکړے شو خو فضل او حقيقت د عيسىٰ مسيح په وسيله راغلل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24935, 'John 1:18', 'John', 1, 18, '&nbsp;هيچا هم چرې خُدائ پاک نۀ دے ليدلے، بلکې بې د يکې يو نه، څوک چې په خپله خُدائ پاک دے، چې د پلار د سترګو تور دے. هم هغۀ مونږ ته خُدائ پاک ښکاره کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24936, 'John 1:19', 'John', 1, 19, '&nbsp;د يحيىٰ ګواهى دا وه، چې کله يهوديانو د يروشلم نه اِمامان او ليويان د دې دپاره ورولېږل چې د هغۀ نه تپوس وکړى چې، ”تۀ څوک يې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24937, 'John 1:20', 'John', 1, 20, '&nbsp;هغۀ صفا ووئيل او اِنکار يې ونۀ کړو چې، ”زۀ مسيح نۀ يم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24938, 'John 1:21', 'John', 1, 21, '&nbsp;نو هغوئ ترې تپوس وکړو چې، ”نو تۀ بيا څوک يې؟ تۀ الياس يې څۀ؟“ هغۀ جواب ورکړو چې، ”نه، زۀ هغه نۀ يم.“ ”تۀ هغه نبى يې څۀ چې مونږ يې په اِنتظار کښې يُو؟“ هغۀ جواب ورکړو چې، ”نه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24939, 'John 1:22', 'John', 1, 22, '&nbsp;بيا هغوئ د هغۀ نه تپوس وکړو چې، ”نو تۀ څوک يې؟ ځکه چې مونږ چا رالېږلى يُو چې هغوئ ته جواب ورکړُو. نو تۀ خپل ځان څۀ ګڼې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24940, 'John 1:23', 'John', 1, 23, '&nbsp;هغۀ ورته جواب ورکړو چې، ”زۀ په بيابان کښې د نعرې وهونکى آواز يم چې نعرې وهى، د مالِک لار نېغه کړئ، لکه چې يشعياه نبى فرمائيلى وُو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24941, 'John 1:24', 'John', 1, 24, '&nbsp;بيا هغه کسان چې فريسيانو رالېږلى وُو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24942, 'John 1:25', 'John', 1, 25, '&nbsp;د هغۀ نه يې تپوس وکړو، ”کۀ نۀ تۀ مسيح يې، نۀ الياس يې، نۀ هغه نبى يې، نو تۀ بيا ولې بپتسمه ورکوې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24943, 'John 1:26', 'John', 1, 26, '&nbsp;يحيىٰ هغوئ ته جواب ورکړو، ”زۀ په اوبو بپتسمه ورکوم خو ستاسو په مينځ کښې يو کس ولاړ دے چې تاسو هغه نۀ پېژنئ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24944, 'John 1:27', 'John', 1, 27, '&nbsp;هغه هغه څوک دے چې زما نه وروستو راځى او زۀ د دې جوګه هم نۀ يم چې د هغۀ د پېزار تسمې پرانيزم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24945, 'John 1:28', 'John', 1, 28, '&nbsp;دا ټولې خبرې د بيتِ‌عنياه په ښار کښې وشوې چې د اُردن بلې غاړې ته دے، چرته چې يحيىٰ بپتسمه ورکوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24946, 'John 1:29', 'John', 1, 29, '&nbsp;بله ورځ يحيىٰ وليدل چې عيسىٰ د هغۀ طرف ته راروان دے. هغۀ وفرمائيل چې، ”وګورئ، د خُدائ پاک ګډورے څوک چې د دُنيا ګناه په ځان وړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24947, 'John 1:30', 'John', 1, 30, '&nbsp;دا هم هغه دے د چا په حقله چې ما وئيلى وُو چې زما نه به وروستو يو کس راځى څوک چې زما نه لوئ دے ځکه چې هغه زما نه مخکښې موجود وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24948, 'John 1:31', 'John', 1, 31, '&nbsp;زۀ په خپله هغه نۀ پېژنم، خو زۀ په دې وجه د اوبو سره د بپتسمې ورکولو دپاره راغلم چې هغه بنى اِسرائيلو ته څرګند شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24949, 'John 1:32', 'John', 1, 32, '&nbsp;بيا يحيىٰ دا ګواهى ورکړله چې، ”ما روحُ القُدس د آسمان نه لکه د يوې کونترې په شان په راکوزېدو وليدلو چې د هغۀ سره پاتې شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24950, 'John 1:33', 'John', 1, 33, '&nbsp;ما په خپله دے نۀ پېژندو، خو هغه چا چې زۀ يې د اوبو د بپتسمې ورکولو دپاره رالېږلے يم هغۀ ما ته وفرمائيل، کله چې زما روح په راکوزېدو ووينې او د چا سره پاتې شى نو هم دا هغه کس دے چې په روحُ القُدس به بپتسمه ورکوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24951, 'John 1:34', 'John', 1, 34, '&nbsp;ما دا په خپله وليدل او زۀ په دې ګواهى کوم چې دا د خُدائ پاک غوره کړے شوے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24952, 'John 1:35', 'John', 1, 35, '&nbsp;په بله ورځ يحيىٰ د خپلو دوو مريدانو سره ولاړ وو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24953, 'John 1:36', 'John', 1, 36, '&nbsp;چې عيسىٰ يې په خوا کښې تېر شو. يحيىٰ هغۀ ته وکتل او وې فرمائيل چې، ”دا د خُدائ پاک ګډُورے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24954, 'John 1:37', 'John', 1, 37, '&nbsp;کله چې هغه دوو مريدانو د هغۀ دا خبره واورېدله نو عيسىٰ پسې روان شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24955, 'John 1:38', 'John', 1, 38, '&nbsp;عيسىٰ چې په شا وکتل نو وې ليدل چې دوئ هغۀ پسې روان دى نو هغۀ ترې تپوس وکړو چې، ”تاسو څۀ ګورئ؟“ هغوئ ووئيل، ”اُستاذه، تۀ کوم ځائ پاتې کېږې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24956, 'John 1:39', 'John', 1, 39, '&nbsp;عيسىٰ جواب ورکړو چې، ”راشئ او وګورئ،“ نو هغوئ د هغۀ سره لاړل او هغه ځائ يې وليدلو چرته چې هغه پاتې کېدو او هغوئ نوره ورځ د هغۀ سره تېره کړله چې دا تېر ماسپښين وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24957, 'John 1:40', 'John', 1, 40, '&nbsp;په هغوئ کښې يو اندرياس د شمعون پطروس ورور وو چا چې هغه خبرې واورېدې کومې چې يحيىٰ کړې وې نو بيا هغه عيسىٰ پسې روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24958, 'John 1:41', 'John', 1, 41, '&nbsp;اول کار چې هغۀ وکړو هغه دا وو چې خپل ورور شمعون يې وموندلو او هغۀ ته يې ووئيل چې، ”مونږ مسيح موندلے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24959, 'John 1:42', 'John', 1, 42, '&nbsp;نو هغۀ شمعون عيسىٰ له راوستو. عيسىٰ هغۀ ته وکتل او وې فرمائيل، ”تۀ د يوحنا زوئ شمعون يې، تا ته به کائفس وئيلے کيږى، يعنې پطروس چې معنىٰ يې ګټ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24960, 'John 1:43', 'John', 1, 43, '&nbsp;بله ورځ عيسىٰ ګليل ته د تلو نيت وکړو. فيليپوس مخې له ورغلو او ورته يې وفرمائيل چې، ”ما پسې راځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24961, 'John 1:44', 'John', 1, 44, '&nbsp;نو فيليپوس د اندرياس او پطروس په شان د بيتِ‌صيدا اوسېدونکے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24962, 'John 1:45', 'John', 1, 45, '&nbsp;فيليپوس نتنى‌ايل له ورغلو او ورته يې ووئيل چې، ”مونږ هغه کس بياموندلو د چا ذکر چې د موسىٰ په شريعت کښې شوے دے او نبيانو کړے دے، چې هغه د ناصرت عيسىٰ د يوسف زوئ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24963, 'John 1:46', 'John', 1, 46, '&nbsp;نتنى‌ايل په حېرانتيا تپوس وکړو چې، ”ناصرت، ولې په ناصرت کښې هم ښۀ څيز پېدا کېدے شى څۀ؟“ فيليپوس جواب ورکړو، ”راشه او په خپله يې وګوره.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24964, 'John 1:47', 'John', 1, 47, '&nbsp;کله چې عيسىٰ نتنى‌ايل په راتلو وليدلو نو وې فرمائيل، ”دا يو رښتينے بنى اِسرائيلى دے، په دۀ کښې هيڅ ټګى نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24965, 'John 1:48', 'John', 1, 48, '&nbsp;نتنى‌ايل ترېنه تپوس وکړو، ”تا زۀ څنګه وپېژندلم؟“ عيسىٰ ورته جواب ورکړو، ”ما تۀ هغه وخت ليدلے وې چې تۀ لا د اينځر د ونې لاندې وې او فيليپوس لا نۀ وې رابللے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24966, 'John 1:49', 'John', 1, 49, '&nbsp;بيا نتنى‌ايل ووئيل، ”اُستاذه. تۀ د خُدائ پاک زوئ يې او تۀ د بنى اِسرائيلو بادشاه يې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24967, 'John 1:50', 'John', 1, 50, '&nbsp;عيسىٰ جواب ورکړو، ”ولې ستا د ايمان د راوړو دغه وجه ده چې تا ته مې وئيل چې تۀ مې د اينځر د ونې لاندې ليدلے وې؟ تۀ به د دې نه هم لوئ لوئ کارونه ووينې.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24968, 'John 1:51', 'John', 1, 51, '&nbsp;بيا هغۀ وفرمائيل، ”زۀ تاسو ټولو ته رښتيا وايم چې تاسو به آسمان پرانستے ووينئ او په اِبن آدم به د خُدائ پاک د فرښتو بره ښکته تلل راتلل ووينئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24969, 'John 2:1', 'John', 2, 1, '&nbsp;په درېمه ورځ د ګليل په قانا نومې ځائ کښې يو وادۀ وو. د عيسىٰ مور هم هلته وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24970, 'John 2:2', 'John', 2, 2, '&nbsp;او عيسىٰ او د هغۀ مريدان هم وادۀ ته رابللے شوى وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24971, 'John 2:3', 'John', 2, 3, '&nbsp;کله چې مے ختم شُو نو د عيسىٰ مور هغۀ ته ووئيل، ”دوئ سره نور مے نشته.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24972, 'John 2:4', 'John', 2, 4, '&nbsp;عيسىٰ جواب ورکړو چې، ”مورې، دا زما کار نۀ دے، زما وخت لا نۀ دے راغلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24973, 'John 2:5', 'John', 2, 5, '&nbsp;خو د هغۀ مور خادِمانو ته ووئيل، ”هر څۀ چې دے درته فرمائى هغه کوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24974, 'John 2:6', 'John', 2, 6, '&nbsp;هلته د کاڼى شپږ چاټۍ خوا په خوا ولاړې وې، دا د يهوديانو د دستور په مطابق د پاکېدو دپاره وې، په هره يوه کښې د شلو نه تر دېرشو ګيلنو پورې ځائ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24975, 'John 2:7', 'John', 2, 7, '&nbsp;عيسىٰ خادِمانو ته وفرمائيل چې، ”دا چاټۍ د اوبو نه ډکې کړئ.“ او هغه هغوئ تر خولې خولې کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24976, 'John 2:8', 'John', 2, 8, '&nbsp;بيا هغۀ هغوئ ته وفرمائيل چې، ”څۀ ترې وباسئ او د مېلمستيا مشر له يې يوسئ.“ او هغوئ هم دغسې وکړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24977, 'John 2:9', 'John', 2, 9, '&nbsp;کله چې د مېلمستيا مشر هغه اوبۀ وڅښلې نو هغه په ميو بدلې شوې وې. خو هغۀ ته د دې پته نۀ وه چې دا د کوم ځائ نه راغلى دى اګر چې نوکرانو ته پته وه چا چې اوبۀ راويستلې وې. نو هغۀ د وادۀ زلمے راوغوښتو', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24978, 'John 2:10', 'John', 2, 10, '&nbsp;او هغۀ ته يې ووئيل، ”هر څوک ښۀ مے اول ورکوى او کمزورى تر هغې ساتى ترڅو چې مېلمانۀ پوره ماړۀ شوى نۀ وى، خو تا خو تر اوسه ښۀ مے لا ساتلى دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24979, 'John 2:11', 'John', 2, 11, '&nbsp;د ګليل په قانا کښې د عيسىٰ دا وړومبۍ معجزه او نښه وه چې عيسىٰ پرې خپله لوئى څرګنده کړه، او د هغۀ مريدانو په هغۀ ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24980, 'John 2:12', 'John', 2, 12, '&nbsp;د دې نه پس عيسىٰ د خپلې مور، وروڼو او مريدانو سره کفرنحُوم ښاريې ته ښکته لاړو او هغوئ هلته يو څو ورځې ايسار شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24981, 'John 2:13', 'John', 2, 13, '&nbsp;د يهوديانو د فسح د اختر ورځې رانزدې وې نو عيسىٰ بره يروشلم ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24982, 'John 2:14', 'John', 2, 14, '&nbsp;هلته هغۀ د خُدائ د کور په دربار کښې د غوَيانو، ګډو او د کونترو خرڅوونکى او صرافان په خپلو کُرسو ناست وليدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24983, 'John 2:15', 'John', 2, 15, '&nbsp;عيسىٰ د پړى کوړه جوړه کړه او د خُدائ د کور نه يې سوداګر، ګډې او غوَيان بهر وشړل. هغۀ د صرافانو تختې نسکورې کړې، او د هغوئ پېسې يې ونوستلې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24984, 'John 2:16', 'John', 2, 16, '&nbsp;بيا هغۀ د کونترو خرڅوونکو ته وفرمائيل، ”دا څيزونه دلته نه اخوا کړئ زما د پلار د کور نه بازار مۀ جوړَوئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24985, 'John 2:17', 'John', 2, 17, '&nbsp;د هغۀ مريدانو ته د صحيفو دا پېشګوئې راياده شوه، ”ستا د کور غېرت به ما وسوزوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24986, 'John 2:18', 'John', 2, 18, '&nbsp;بيا يهوديانو عيسىٰ ورټلو او تپوس يې ترې وکړو چې، ”تۀ مونږ ته داسې څۀ معجزه ښودلے شې چې تۀ دا ثابت کړې چې دا اختيار تا سره شته؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24987, 'John 2:19', 'John', 2, 19, '&nbsp;عيسىٰ جواب ورکړو چې، ”دا د خُدائ کور ونړوئ او زۀ به يې په درېو ورځو کښې بيا ودروم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24988, 'John 2:20', 'John', 2, 20, '&nbsp;بيا يهوديانو ووئيل، ”دا د خُدائ کور خو په شپږ څلوېښت کاله کښې جوړ شوے دے، او تۀ يې راته په درېو ورځو کښې ودروې؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24989, 'John 2:21', 'John', 2, 21, '&nbsp;خو د خُدائ د کوم کور ذکر چې عيسىٰ کولو هغه د دۀ خپل بدن وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24990, 'John 2:22', 'John', 2, 22, '&nbsp;د هغۀ د بيا راژوندى کېدو نه پس د هغۀ مريدانو ته راياد شول چې هغۀ څۀ فرمائيلى وُو نو د هغوئ په صحيفو او د عيسىٰ په وينا يقين راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24991, 'John 2:23', 'John', 2, 23, '&nbsp;کله چې عيسىٰ د فسح د اختر دپاره په يروشلم کښې دېره وو نو خلقو هغه معجزې وليدې کومې چې هغۀ ښکاره کړې او ډېرو خلقو په هغۀ ايمان راوړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24992, 'John 2:24', 'John', 2, 24, '&nbsp;خو عيسىٰ په خپله په هغوئ اعتبار نۀ کولو ځکه چې هغۀ ټول خلق ډېر ښۀ پېژندل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24993, 'John 2:25', 'John', 2, 25, '&nbsp;او د بل چا د پوهولو ضرورت ورته نۀ وو ځکه چې هغه د ټولو خلقو د فطرت نه ښۀ خبر وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24994, 'John 3:1', 'John', 3, 1, '&nbsp;په فريسيانو کښې نيکوديموس نومې يو سړے وو چې د يهوديانو د جرګې مشر وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24995, 'John 3:2', 'John', 3, 2, '&nbsp;هغه عيسىٰ له د شپې راغلو او ورته يې ووئيل چې، ”اُستاذه، مونږ ته معلومه ده چې تۀ هم هغه اُستاذ يې چې خُدائ پاک رالېږلے يې. ځکه چې هيڅوک هم دا معجزې چې ته يې کوې نۀ شى کولے خو کۀ خُدائ پاک ورسره مل نۀ وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24996, 'John 3:3', 'John', 3, 3, '&nbsp;عيسىٰ جواب ورکړو، ”زۀ تاسو ته رښتيا وايم، هيڅوک هم د خُدائ پاک بادشاهى نۀ شى ليدلے ترڅو چې هغه بيا پېدا نۀ شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24997, 'John 3:4', 'John', 3, 4, '&nbsp;نيکوديموس هغۀ ته ووئيل، ”نو بيا دا څنګه ممکنه ده چې يو سړے چې بوډا وى نو هغه به بيا څنګه پېدا شى؟ ولې څوک په دوېم ځل د مور ګېډې ته ورننوتے شى څۀ او بيا پېدا کېدے شى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24998, 'John 3:5', 'John', 3, 5, '&nbsp;عيسىٰ جواب ورکړو، ”زۀ درته رښتيا وايم چې هيڅوک هم د خُدائ پاک بادشاهۍ ته نۀ شى داخلېدے ترڅو چې هغه د اوبو او روحُ القُدس نه پېدا نۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24999, 'John 3:6', 'John', 3, 6, '&nbsp;چې د انسان نه پېدا کيږى هغه جسم دے خو چې د روحُ القُدس نه پېدا کيږى هغه روح دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(25000, 'John 3:7', 'John', 3, 7, '&nbsp;زۀ چې تاسو ته دا ووايم چې تاسو له بيا پېدا کېدل په کار دى نو په دې حېرانېږئ مه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');